 DeparturePreview317 PreviewInfo317(RaidMap map){var info=new DeparturePreview317{MinX=map.Bounds.xMin,MinZ=map.Bounds.yMin,Width=map.Bounds.width,Height=map.Bounds.height,Spawn=map.Spawn};info.Exits.AddRange(map.Exits);if(map.HarborWhitebox){for(int i=1;i<Mathf.Min(map.RegionAnchors.Count,RaidMap.WhiteboxNames.Length);i++){info.Areas.Add(map.RegionAnchors[i]);info.Names.Add(RaidMap.WhiteboxNames[i]);}info.Areas.Add(new Vector3(RaidMap.FreightExteriorBounds2716.center.x,0,RaidMap.FreightExteriorBounds2716.center.y));info.Names.Add("西北货运场");}else {for(int i=1;i<Mathf.Min(map.ExteriorAreaPoints.Count,RaidMap.ExteriorAreaNames.Length)-1;i++){info.Areas.Add(map.ExteriorAreaPoints[i]);info.Names.Add(RaidMap.ExteriorAreaNames[i]);}}return info;}
 Texture2D TrainingPreview317(RaidMap map){int w=Mathf.RoundToInt(map.Bounds.width*12),h=Mathf.RoundToInt(map.Bounds.height*12);var colors=new Color32[w*h];Color32 ground=PixelArt.Hex("64756E");for(int i=0;i<colors.Length;i++)colors[i]=ground;foreach(var c in map.Root.GetComponentsInChildren<Collider>()){if(!c.enabled||c.isTrigger||c.GetComponentInParent<RaidActor>()||(SceneObstacle.MovementMask&(1<<c.gameObject.layer))==0)continue;var b=c.bounds;int x0=Mathf.Clamp(Mathf.FloorToInt((b.min.x-map.Bounds.xMin)*12),0,w-1),x1=Mathf.Clamp(Mathf.CeilToInt((b.max.x-map.Bounds.xMin)*12),0,w-1),z0=Mathf.Clamp(Mathf.FloorToInt((b.min.z-map.Bounds.yMin)*12),0,h-1),z1=Mathf.Clamp(Mathf.CeilToInt((b.max.z-map.Bounds.yMin)*12),0,h-1);var col=PixelArt.Hex(c.gameObject.layer==SceneObstacle.LowLayer?"A19574":"BDCAC0");for(int z=z0;z<=z1;z++)for(int x=x0;x<=x1;x++)colors[z*w+x]=col;}var image=new Texture2D(w,h,TextureFormat.RGBA32,false){name="TrainingDeparture317",filterMode=FilterMode.Point};image.SetPixels32(colors);image.Apply();return image;}
