 IEnumerator ExportDeparturePreviews317(){FreshCamp();G.enabled=false;G.HarborWalkthrough=true;G.ModRange315=false;Check(G.BeginTraining(),"317 isolated harbor preview starts");yield return null;Physics.SyncTransforms();Check(G.Map.HarborWhitebox,"317 exported harbor is current full map");WritePreview317("Harbor",G.Map.HarborPlanTexture(),PreviewInfo317(G.Map));G.Finish(false);yield return null;G.HarborWalkthrough=false;Check(G.BeginTraining(),"317 isolated training preview starts");yield return null;Physics.SyncTransforms();var image=TrainingPreview317(G.Map);WritePreview317("Training",image,PreviewInfo317(G.Map));Destroy(image);G.Finish(false);results.Add("DEPARTURE PREVIEW EXPORT317 COMPLETE");yield return null;}
 IEnumerator RunDeparture317(){FreshCamp();G.enabled=false;G.Controls=new TouchInput();G.OpenCampPage315(CampPage315.Departure);var originalMap=G.Map;string save=JsonUtility.ToJson(G.Save);Check(G.SelectDepartureMap317(RaidDestination.Harbor)&&G.SetDepartureHard317(true)&&G.HardMode,"317 harbor hard mode selection");Check(G.SetDepartureHard317(false)&&!G.HardMode,"317 harbor normal mode selection");Check(G.SelectDepartureMap317(RaidDestination.Training)&&!G.SetDepartureHard317(true)&&!G.HardMode,"317 training has no difficulty switch");Check(!G.SelectDepartureMap317((RaidDestination)99)&&G.NextMap==RaidDestination.Training,"317 only existing two maps selectable");var ui=G.GetComponent<RaidUI>();foreach(var target in new[]{RaidDestination.Harbor,RaidDestination.Training}){G.SelectDepartureMap317(target);var image=ui.DepartureImage317(target);Check(image!=null&&image.width>100&&image.height>100,"317 deployed preview loads "+target);yield return null;yield return null;}Check(G.Map==originalMap&&G.Phase==GamePhase.Base&&!G.TrainingActive&&JsonUtility.ToJson(G.Save)==save,"317 selection previews do not build maps or alter saved gear");G.Equipped=null;G.SelectDepartureMap317(RaidDestination.Harbor);Check(!G.CanConfirmDeparture317,"317 harbor rejects no weapon");G.SelectDepartureMap317(RaidDestination.Training);Check(G.CanConfirmDeparture317,"317 training allows entry without own weapon");G.CampLocked=true;Check(!G.CanConfirmDeparture317,"317 unavailable save rejects departure");G.CampLocked=false;G.Paused=true;Check(!G.CanConfirmDeparture317,"317 paused departure blocked");G.Paused=false;Check(G.StartRaid()&&G.TrainingActive&&G.Map.ExteriorPreview&&!G.ModRange315,"317 selected training enters existing training map");G.Finish(false);G.OpenCampPage315(CampPage315.Departure);Check(G.MenuCamp315&&G.CampPage315==CampPage315.Departure,"317 return permits departure reselection");FreshCamp();G.enabled=false;G.OpenCampPage315(CampPage315.Departure);G.SelectDepartureMap317(RaidDestination.Harbor);G.SetDepartureHard317(true);G.Magazine=0;G.StoreActiveMagazine314();Check(G.CanConfirmDeparture317&&G.StartRaid()&&!G.TrainingActive&&G.ActiveHardMode&&G.Magazine==0,"317 harbor uses chosen hard mode and retains empty magazine");G.Finish(true);Check(G.MenuCamp315&&G.CampPage315==CampPage315.Home,"317 extraction returns main menu");G.OpenCampPage315(CampPage315.Departure);var input=new TouchInput{PausePressed=true};G.Controls=input;G.TickCamp(.01f);Check(G.CampPage315==CampPage315.Home,"317 Esc returns menu without loadout UI");G.OpenCampPage315(CampPage315.Departure);yield return Photo301("3.0.17-departure-native.png");results.Add("DEPARTURE317 COMPLETE");}
